      referralLabel: "إحالة مباشرة من مستوى واحد", referralTitle: "خصم واضح لمتعلم حقيقي — لا لبناء شبكة.", referralText: "في برامج الأكاديمية المدفوعة المؤهلة، قد يحصل الداعي والمتعلم الجديد على خصم ١٠٪ لكل منهما لفترة دفع واحدة بعد نهائية الدفعة الأولى. لا مبالغ نقدية، ولا مستويات لاحقة، ولا فرق، ولا أرباح من دعوات الآخرين.", referralAction: "ادعُ إلى الأكاديمية",
